export interface ConnectorConfig {
  /** Trello API key from https://trello.com/app-key */
  trelloApiKey: string
  /** Trello API token (user-specific) */
  trelloApiToken: string
  /** ID of the Trello checklist to add items to */
  checklistId: string
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface CalendarEventPayload {
  event: string
  event_id: string
  account_id: string
  summary: string
  start: { dateTime: string }
  end: { dateTime: string }
  attendees?: Array<{
    email: string
    displayName: string
    responseStatus: string
  }>
}

export interface ChecklistItemResult {
  id: string
  idChecklist: string
  name: string
  state: string
  pos: number
}

export async function handle(
  payload: CalendarEventPayload,
  config: ConnectorConfig,
): Promise<ChecklistItemResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.summary) {
    throw new Error('Missing required field: summary')
  }

  if (!payload.attendees || payload.attendees.length === 0) {
    throw new Error('Missing required field: attendees (at least one attendee with email required)')
  }

  const firstAttendee = payload.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('Missing required field: attendees[0].email')
  }

  const url = `https://api.trello.com/1/checklists/${encodeURIComponent(config.checklistId)}/checkItems`
  const params = new URLSearchParams({
    key: config.trelloApiKey,
    token: config.trelloApiToken,
  })

  const body = {
    value: firstAttendee.email,
    name: payload.summary,
    pos: 'top',
  }

  const response = await fetchImpl(`${url}?${params.toString()}`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Trello API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  return (await response.json()) as ChecklistItemResult
}

